/**
 * Validate minimal payload for Lane A ingestion.
 * Expected JSON:
 * {
 *   "env": "dev|test|prod",
 *   "jobType": "selective|nightly|adhoc",
 *   "source": {
 *     "filePath": "/data/uploads/your.pdf",
 *     "filename": "your.pdf",
 *     "expectedSha256": "optional hex",
 *     "lane": "A",
 *     "system": "PF1E|PF2E|DND5E|...",
 *     "publisher": "optional",
 *     "title": "optional"
 *   }
 * }
 */
const items = $input.all();
return items.map(item => {
  const j = item.json || {};
  const src = j.source || {};
  const env = (j.env || 'dev').toLowerCase();
  if (!['dev','test','prod'].includes(env)) {
    throw new Error('Invalid env. Use dev|test|prod');
  }
  if (!src.filePath) {
    throw new Error('source.filePath is required and must be a mounted path inside n8n container.');
  }
  // Normalize job id
  const jobId = j.jobId || (`${j.jobType || 'adhoc'}_${Date.now()}_${env}`);
  return {
    json: {
      ...j,
      env,
      jobId,
      source: {
        lane: 'A',
        ...src
      }
    }
  };
});

const crypto = require('crypto');
const items = $input.all();
return items.map(item => {
  const bin = item.binary?.file;
  if (!bin) {
    throw new Error('Binary not loaded on property "file".');
  }
  const buffer = Buffer.from(bin.data, bin.encoding || 'base64');
  const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
  const expected = (item.json.source.expectedSha256 || '').toLowerCase().trim();
  const verified = expected ? (sha256.toLowerCase() === expected) : null;
  return {
    json: {
      ...item.json,
      gate0: {
        sha256,
        expectedSha256: expected || null,
        verified
      }
    },
    binary: item.binary
  };
});

/**
 * Placeholder for a pre-existing chunk registry.
 * For now, just attach 'chunkCountKnown': false.
 * You can later call your registry DB and compare counts.
 */
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    gate0: {
      ...item.json.gate0,
      chunkCountKnown: false,
      chunkCountMatches: null
    }
  },
  binary: item.binary
}));

/**
 * Build logical chunks using TOC hints and page windowing (20-30 pages per chunk).
 * Input: Pass A elements
 * Output: array of chunk descriptors [{startPage, endPage, label}, ...]
 */
function buildChunksFromTOC(elements) {
  const MAX_PAGES = 30;
  const MIN_PAGES = 20;
  // Extract page breaks from elements that look like headings with page_number
  const tocPages = [];
  for (const el of (elements || [])) {
    if (el && typeof el === 'object' && (el.type?.toLowerCase() || '').includes('title')) {
      const p = el.metadata?.page_number;
      if (Number.isInteger(p)) tocPages.push(p);
    }
  }
  tocPages.sort((a,b)=>a-b);
  // Fallback if no TOC
  if (tocPages.length === 0) {
    return [{ startPage: 1, endPage: MAX_PAGES, label: 'chunk-1' }];
  }
  const chunks = [];
  let currentStart = tocPages[0];
  for (let i=1; i<tocPages.length; i++) {
    const next = tocPages[i];
    if ((next - currentStart) >= MIN_PAGES) {
      const end = Math.min(currentStart + MAX_PAGES - 1, next-1);
      chunks.push({ startPage: currentStart, endPage: end, label: `chunk-${chunks.length+1}` });
      currentStart = next;
    }
  }
  // tail
  chunks.push({ startPage: currentStart, endPage: currentStart + MAX_PAGES - 1, label: `chunk-${chunks.length+1}` });
  return chunks;
}

const items = $input.all();
return items.map(item => {
  const elements = item.json?.data;
  // httpRequest stores JSON under item.json when response is JSON
  // In n8n, it can be item.json for JSON responses.
  const chunks = buildChunksFromTOC(elements);
  return {
    json: {
      ...item.json,
      passA: { tocExtracted: true, elementCount: Array.isArray(elements)? elements.length : 0 },
      passB: { chunks }
    },
    binary: item.binary
  };
});

/**
 * Prepare body for Unstructured extraction for the current chunk window.
 */
const items = $input.all();
return items.map(item => {
  const chunks = item.json.passB.chunks;
  const idx = item.json._chunkIndex || 0;
  const chunk = chunks[idx];
  if (!chunk) {
    return item; // no-op
  }
  return {
    json: {
      ...item.json,
      currentChunk: chunk,
      _chunkIndex: idx
    },
    binary: item.binary
  };
});

/**
 * Assemble a partial manifest result for this chunk.
 * In a full system, this would merge into a job-level manifest document.
 */
const items = $input.all();
return items.map(item => {
  const now = new Date().toISOString();
  return {
    json: {
      ...item.json,
      passF: {
        manifest: {
          jobId: item.json.jobId,
          env: item.json.env,
          chunkLabel: item.json.currentChunk?.label,
          sha256: item.json.gate0?.sha256,
          timestamp: now
        }
      }
    },
    binary: item.binary
  };
});

/**
 * Increment chunk index and decide to continue or finish.
 */
const items = $input.all();
return items.map(item => {
  const chunks = item.json.passB?.chunks || [];
  const idx = (item.json._chunkIndex || 0) + 1;
  const hasMore = idx < chunks.length;
  return {
    json: { ...item.json, _chunkIndex: idx, _hasMore: hasMore },
    binary: item.binary
  };
});

/**
 * Aggregate job-level summary at the end of all chunks.
 * In a full system, you would maintain an array of chunk results in static data.
 */
const items = $input.all();
return items.map(item => {
  return {
    json: {
      jobId: item.json.jobId,
      env: item.json.env,
      source: item.json.source,
      gate0: item.json.gate0,
      passA: item.json.passA,
      chunkCount: (item.json.passB?.chunks || []).length,
      status: 'completed'
    }
  };
});

/**
 * Shape error for logging/observability.
 */
const items = $input.all();
return items.map(item => {
  const e = item.json;
  return {
    json: {
      error: {
        message: e.message,
        stack: e.stack,
        node: e.node?.name,
        time: new Date().toISOString()
      }
    }
  };
});
